MODULE DIST_GRID_ARGS_INFO_MOD

USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT

IMPLICIT NONE

PRIVATE
PUBLIC :: ARGS_INFO

! Shapes of the array arguments to DIST_GRID, passed to the C++ layer so that it can reconstruct
! the array bounds from the bare data pointers.
TYPE, BIND(C) :: ARGS_INFO
  INTEGER(KIND=C_INT) :: IPGPG_SHAPE(2)
  INTEGER(KIND=C_INT) :: IKFROM_SHAPE(1)
  INTEGER(KIND=C_INT) :: IGP_SHAPE(3)
  INTEGER(KIND=C_INT) :: IKSORT_SHAPE(1)
END TYPE ARGS_INFO

END MODULE DIST_GRID_ARGS_INFO_MOD

SUBROUTINE DIST_GRID(PGPG, KPROMA, KFDISTG, KFROM, KRESOL, PGP, KSORT)

USE PARKIND1,                    ONLY: JPRB, JPIM
USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_INT, C_PTR, C_LOC, C_NULL_PTR
USE DIST_GRID_ARGS_INFO_MOD,     ONLY: ARGS_INFO

IMPLICIT NONE

INTERFACE
SUBROUTINE DIST_GRID_CPP_BINDING_SP(ARGS, KPROMA, KFDISTG, KRESOL, PGPG, KFROM, PGP, KSORT) &
  &  BIND(C, NAME="dist_grid_sp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_FLOAT, C_INT, C_PTR
  USE DIST_GRID_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KPROMA
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KFDISTG
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KRESOL
  REAL(KIND=C_FLOAT),  OPTIONAL, INTENT(IN)  :: PGPG(*)
  INTEGER(KIND=C_INT),           INTENT(IN)  :: KFROM(*)
  REAL(KIND=C_FLOAT),            INTENT(OUT) :: PGP(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KSORT(*)
END SUBROUTINE DIST_GRID_CPP_BINDING_SP
SUBROUTINE DIST_GRID_CPP_BINDING_DP(ARGS, KPROMA, KFDISTG, KRESOL, PGPG, KFROM, PGP, KSORT) &
  &  BIND(C, NAME="dist_grid_dp")
  USE, INTRINSIC :: ISO_C_BINDING, ONLY: C_DOUBLE, C_INT, C_PTR
  USE DIST_GRID_ARGS_INFO_MOD, ONLY: ARGS_INFO
  TYPE(ARGS_INFO),               INTENT(IN)  :: ARGS
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KPROMA
  INTEGER(KIND=C_INT), VALUE,    INTENT(IN)  :: KFDISTG
  TYPE(C_PTR),         VALUE,    INTENT(IN)  :: KRESOL
  REAL(KIND=C_DOUBLE), OPTIONAL, INTENT(IN)  :: PGPG(*)
  INTEGER(KIND=C_INT),           INTENT(IN)  :: KFROM(*)
  REAL(KIND=C_DOUBLE),           INTENT(OUT) :: PGP(*)
  INTEGER(KIND=C_INT), OPTIONAL, INTENT(IN)  :: KSORT(*)
END SUBROUTINE DIST_GRID_CPP_BINDING_DP
END INTERFACE

REAL(KIND=JPRB),    OPTIONAL, INTENT(IN)  :: PGPG(:,:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KPROMA
INTEGER(KIND=JPIM),           INTENT(IN)  :: KFDISTG
INTEGER(KIND=JPIM),           INTENT(IN)  :: KFROM(:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KRESOL
REAL(KIND=JPRB),              INTENT(OUT) :: PGP(:,:,:)
INTEGER(KIND=JPIM), OPTIONAL, INTENT(IN)  :: KSORT(:)

TYPE(ARGS_INFO) :: ARGS

! C-interoperable handles for the optional scalar arguments. A null C pointer indicates the
! argument was not present in the Fortran call; otherwise the pointer targets a local temporary.
TYPE(C_PTR) :: KPROMA_PTR, KRESOL_PTR
INTEGER(KIND=C_INT), TARGET :: IPROMA, IRESOL

IF (PRESENT(PGPG)) THEN
  ARGS%IPGPG_SHAPE = SHAPE(PGPG, KIND=C_INT)
ELSE
  ARGS%IPGPG_SHAPE = 0_C_INT
ENDIF
ARGS%IKFROM_SHAPE = SHAPE(KFROM, KIND=C_INT)
ARGS%IGP_SHAPE = SHAPE(PGP, KIND=C_INT)
IF (PRESENT(KSORT)) THEN
  ARGS%IKSORT_SHAPE = SHAPE(KSORT, KIND=C_INT)
ELSE
  ARGS%IKSORT_SHAPE = 0_C_INT
ENDIF

IF (PRESENT(KPROMA)) THEN
  IPROMA = KPROMA
  KPROMA_PTR = C_LOC(IPROMA)
ELSE
  KPROMA_PTR = C_NULL_PTR
ENDIF
IF (PRESENT(KRESOL)) THEN
  IRESOL = KRESOL
  KRESOL_PTR = C_LOC(IRESOL)
ELSE
  KRESOL_PTR = C_NULL_PTR
ENDIF

#ifdef TRANS_SINGLE
CALL DIST_GRID_CPP_BINDING_SP(ARGS, KPROMA_PTR, KFDISTG, KRESOL_PTR, PGPG=PGPG, KFROM=KFROM, &
  &                           PGP=PGP, KSORT=KSORT)
#else
CALL DIST_GRID_CPP_BINDING_DP(ARGS, KPROMA_PTR, KFDISTG, KRESOL_PTR, PGPG=PGPG, KFROM=KFROM, &
  &                           PGP=PGP, KSORT=KSORT)
#endif

END SUBROUTINE DIST_GRID
